typedef int axis_id_t;
typedef float rational_t;

enum PS2_Axes
{
  JOY_PS2_DX,
  JOY_PS2_DY,
  JOY_PS2_X,
  JOY_PS2_Y,
  JOY_PS2_LX,
  JOY_PS2_LY,
  JOY_PS2_BTNL3,
  JOY_PS2_RX,
  JOY_PS2_RY,
  JOY_PS2_BTNR3,
  JOY_PS2_BTNX,
  JOY_PS2_BTNO,
  JOY_PS2_DUMMMY1,
  JOY_PS2_BTNSQ,
  JOY_PS2_BTNTR,
  JOY_PS2_DUMMMY2,
  JOY_PS2_BTNL1,
  JOY_PS2_BTNR1,
  JOY_PS2_BTNL2,
  JOY_PS2_BTNR2,
  JOY_PS2_START,
  JOY_PS2_SELECT,
  JOY_PS2_DISCONNECT,
  JOY_PS2_NUM_AXES
};

#define assert(x) ((void)0)

class AISurferController
{
  char data[220];
  float oldX, oldY, oldXRight, oldYRight;
  int oldButtonX, oldButtonO, oldButtonSq, oldButtonTr;
  int oldButtonL1, oldButtonL2, oldButtonL3, oldButtonR1, oldButtonR2, oldButtonR3;
  int oldButtonSelect, oldButtonStart;

public:
  rational_t get_axis_old_state(axis_id_t axis, int control_axis) const;
};

rational_t AISurferController::get_axis_old_state(axis_id_t axis, int control_axis ) const
{
   switch (axis) 
  {
    case JOY_PS2_X: // left analog horiz
      return oldX;

    case JOY_PS2_Y: // left analog vert
      return oldY;

    case JOY_PS2_DX: // just Dpad
      if (oldX < 0)
      {
          return -1.0f;
      }
      else if (oldX > 0)
      {
          return 1.0f;
      }
      return 0.0f;

    case JOY_PS2_DY: // just Dpad -1 = up
      if (oldY < 0)
      {
          return -1.0f;  //up
      }
      else if (oldY > 0)
      {
          return 1.0f;
      }
      return 0.0f;

    case JOY_PS2_LX: //  - 1 = left
      return oldX;
    case JOY_PS2_LY: // -1 = up
      return oldY;
    case JOY_PS2_RX: 
      return oldXRight;
    case JOY_PS2_RY: 
      return oldYRight;

    case JOY_PS2_BTNL3: // L3
      return oldButtonL3;
    case JOY_PS2_BTNR3: 
      return oldButtonR3;
    case JOY_PS2_BTNX:  // A (ps2 x)
      return oldButtonX;
    case JOY_PS2_BTNO:  // B (ps2 o)
        return oldButtonO;
    case JOY_PS2_BTNSQ: // X (ps2 sq)
        return oldButtonSq;
    case JOY_PS2_BTNTR: // Y (ps2 tr)
        return oldButtonTr;

    case JOY_PS2_BTNR1: // C (ps2 R1)
        return oldButtonR1;
    case JOY_PS2_BTNR2: // R (ps2 R2)
        return oldButtonR2;

    case JOY_PS2_BTNL1: // Z (ps2 L1)
        return oldButtonL1;
    case JOY_PS2_BTNL2: // L (ps2 L2)
        return oldButtonL2;


    case JOY_PS2_START: // Start
      return oldButtonStart;
    case JOY_PS2_SELECT:
      return oldButtonSelect;

    default:
      assert("ps2_joypad_device::get_axis_state illegal axis queried." == 0);
      return 0.0f;

  }

}
